<script setup lang="ts">
/**
 * Tree.Node: one item of the tree: its row and, when it is an open branch, the rows under it.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, useId } from 'vue'

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/tree.module.css'
import Spinner from './Spinner.vue'
import type { TreeItem, TreeMessages } from './Tree.vue'

export interface TreeNodeProps {
  item: TreeItem
  /**
   * The level it sits at: 0 at the top.
   */
  level: number
  /**
   * The open branches by id.
   */
  open: ReadonlySet<string>
  /**
   * The selected item's id.
   */
  selected: string | null
  messages: TreeMessages
}

defineOptions({ name: 'TreeNode', inheritAttrs: false })

const props = defineProps<TreeNodeProps>()
const uid = useId()
const under = computed(() => props.item.children ?? [])
const branch = computed(() => under.value.length > 0 || props.item.hasChildren === true)
const disabled = computed(() => props.item.disabled === true)
const expanded = computed(() => branch.value && !disabled.value && props.open.has(props.item.id))
const loading = computed(() => props.item.loading === true)
const hasMore = computed(() => props.item.hasMore === true)
const chosen = computed(() => !disabled.value && props.selected === props.item.id)
</script>

<template>
  <li
    :class="styles.item"
    role="treeitem"
    :aria-labelledby="`${uid}-label`"
    :aria-describedby="item.description === undefined ? undefined : `${uid}-description`"
    :aria-expanded="branch ? expanded : undefined"
    :aria-selected="disabled ? undefined : chosen"
    :aria-disabled="disabled ? true : undefined"
    :aria-busy="expanded && loading ? true : undefined"
    :data-tree-item="item.id"
    :data-selected="chosen ? '' : undefined"
    :data-disabled="disabled ? '' : undefined"
  >
    <!-- row -->
    <div :class="styles.row" :style="{ '--pm-tree-level': level }" data-tree-part="row">
      <!-- toggle -->
      <span v-if="branch" :class="styles.toggle" data-tree-part="toggle" aria-hidden="true">
        <span :class="styles.chevron">
          <Icon name="next" size="sm" />
        </span>
      </span>
      <span v-else :class="styles.slot" />
      <span :class="styles.text">
        <!-- label -->
        <span :class="styles.label" :id="`${uid}-label`">
          {{ item.label }}
        </span>
        <!-- description -->
        <span
          v-if="item.description !== undefined"
          :class="styles.description"
          :id="`${uid}-description`"
        >
          {{ item.description }}
        </span>
      </span>
    </div>
    <!-- group -->
    <ul
      v-if="expanded && (under.length > 0 || loading || hasMore)"
      :class="styles.group"
      role="group"
    >
      <template v-for="child in under" :key="child.id">
        <TreeNode
          :item="child"
          :level="level + 1"
          :open="open"
          :selected="selected"
          :messages="messages"
        />
      </template>
      <!-- more -->
      <li
        v-if="hasMore"
        :class="styles.item"
        role="treeitem"
        :aria-labelledby="`${uid}-more`"
        aria-selected="false"
        :aria-busy="loading ? true : undefined"
        data-tree-part="more"
      >
        <div
          :class="styles.row"
          :style="{ '--pm-tree-level': level + 1 }"
          data-tree-part="row"
          :data-busy="loading ? '' : undefined"
        >
          <span :class="styles.slot">
            <Spinner v-if="loading" size="sm" :label="messages.loading" />
          </span>
          <span :class="styles.text">
            <span :class="styles.more" :id="`${uid}-more`">
              {{ loading ? messages.loading : messages.loadMore }}
            </span>
          </span>
        </div>
      </li>
      <!-- busy -->
      <li v-else-if="loading" :class="styles.item" role="none">
        <div :class="styles.row" :style="{ '--pm-tree-level': level + 1 }" data-busy="">
          <span :class="styles.slot">
            <Spinner size="sm" :label="messages.loading" />
          </span>
          <span :class="styles.text">
            <span :class="styles.status" aria-hidden="true">
              {{ messages.loading }}
            </span>
          </span>
        </div>
      </li>
    </ul>
  </li>
</template>
